pm.test("Crear producto válido responde 201 Created", () => {
    pm.response.to.have.status(201);
});
pm.test("El body trae id numérico y el nombre enviado", () => {
    const b = pm.response.json();
    pm.expect(b.id).to.be.a("number");
    pm.expect(b.nombre).to.eql("Teclado mecánico");
    pm.collectionVariables.set("productoId", b.id);
});
pm.test("Tiempo de respuesta menor a 2000ms", () => {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Obtener por id responde 200 OK", () => {
    pm.response.to.have.status(200);
});
pm.test("El body corresponde al producto creado", () => {
    const b = pm.response.json();
    pm.expect(b.nombre).to.eql("Teclado mecánico");
    pm.expect(b.id).to.eql(Number(pm.collectionVariables.get("productoId")));
});

pm.test("Listar por categoría responde 200 OK", () => {
    pm.response.to.have.status(200);
});
pm.test("El body es un arreglo que incluye el producto creado", () => {
    const b = pm.response.json();
    pm.expect(b).to.be.an("array");
    pm.expect(b.some(p => p.nombre === "Teclado mecánico")).to.be.true;
});

pm.test("Producto inexistente responde 404 Not Found", () => {
    pm.response.to.have.status(404);
});
pm.test("El body indica que no fue encontrado", () => {
    pm.expect(pm.response.text()).to.include("no encontrado");
});
